class Solution:
    def singleNonDuplicate(self, nums: List[int]) -> int:
        n = len(nums)
        lo, hi = 0, n - 1

        while lo <= hi:
            mid = (lo + hi)// 2

            if n == 1 or (mid == 0 and nums[mid] != nums[mid + 1]) or (mid == n - 1 and nums[mid] != nums[mid - 1]) or nums[mid - 1] != nums[mid] != nums[mid +1]:
                return nums[mid]
            if nums[mid] == nums[mid - 1]:
                if mid % 2 == 1:
                    lo = mid + 1
                else:
                    hi = mid - 1
            elif nums[mid] == nums[mid + 1]:
                if mid % 2 == 1:
                    hi = mid - 1
                else:
                    lo = mid + 1

        return -1
